insert into public.learning_content
(content_id, faculty, subject, content_type, access_tier, display_order, content_data, is_published)
values
('dph-pm-extra-mcq-01','Pharmacy','Diploma in Pharmacy','mcq','free',1401,'{"question":"The main purpose of pharmaceutical management is to:","translation":"औषधि व्यवस्थापनको मुख्य उद्देश्य के हो?","options":["Ensure safe, effective and economical medicine supply","Increase medicine prices","Promote only branded products","Avoid stock records"],"correctIndex":0,"explanation":"It coordinates selection, procurement, storage and distribution so medicines remain available and safe.","explanationNe":"यसले औषधिको छनोट, खरिद, भण्डारण र वितरणलाई समन्वय गरी सुरक्षित उपलब्धता सुनिश्चित गर्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-02','Pharmacy','Diploma in Pharmacy','mcq','free',1402,'{"question":"Which activity normally comes first in the medicine supply cycle?","translation":"औषधि आपूर्ति चक्रमा सामान्यतया सुरुमा कुन काम आउँछ?","options":["Distribution","Selection","Disposal","Issuing"],"correctIndex":1,"explanation":"Selection defines which medicines are needed before quantification and procurement.","explanationNe":"खरिद र परिमाण निर्धारण गर्नुअघि कुन औषधि आवश्यक छन् भन्ने छनोट गरिन्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-03','Pharmacy','Diploma in Pharmacy','mcq','free',1403,'{"question":"An essential medicines list helps to:","translation":"अत्यावश्यक औषधि सूचीले केमा मद्दत गर्छ?","options":["Promote every available brand","Limit rational selection to priority medicines","Replace prescriptions","Remove quality checks"],"correctIndex":1,"explanation":"It prioritizes medicines based on public health relevance, efficacy, safety and cost-effectiveness.","explanationNe":"यसले जनस्वास्थ्य आवश्यकता, प्रभावकारिता, सुरक्षा र लागत प्रभावकारिताका आधारमा औषधिलाई प्राथमिकता दिन्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-04','Pharmacy','Diploma in Pharmacy','mcq','free',1404,'{"question":"The best basis for estimating routine medicine requirements is:","translation":"नियमित औषधि आवश्यकता अनुमान गर्ने राम्रो आधार कुन हो?","options":["Guesswork","Consumption and morbidity data","Supplier preference","Shelf appearance"],"correctIndex":1,"explanation":"Past consumption, disease patterns, stock status and lead time inform forecasting.","explanationNe":"अघिल्लो खपत, रोगको अवस्था, मौज्दात र आपूर्ति समयका आधारमा अनुमान गरिन्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-05','Pharmacy','Diploma in Pharmacy','mcq','free',1405,'{"question":"Lead time means the time between:","translation":"Lead time भन्नाले कुन अवधिलाई जनाउँछ?","options":["Manufacture and expiry","Ordering and receiving supplies","Opening and closing a shop","Prescription and counselling"],"correctIndex":1,"explanation":"Lead time is the interval from placing an order until the goods are received and available.","explanationNe":"अर्डर गरेको समयदेखि सामान प्राप्त भएर उपलब्ध हुने समयसम्मको अवधि हो।"}'::jsonb,true),
('dph-pm-extra-mcq-06','Pharmacy','Diploma in Pharmacy','mcq','free',1406,'{"question":"A buffer stock is maintained mainly to:","translation":"Buffer stock किन राखिन्छ?","options":["Increase expiry","Cover unexpected demand or delays","Avoid stock records","Replace quality assurance"],"correctIndex":1,"explanation":"Buffer stock protects against uncertainty in demand and replenishment.","explanationNe":"माग वा आपूर्तिमा अनिश्चितता हुँदा औषधि अभाव हुन नदिन अतिरिक्त मौज्दात राखिन्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-07','Pharmacy','Diploma in Pharmacy','mcq','free',1407,'{"question":"A stock-out occurs when:","translation":"Stock-out कहिले हुन्छ?","options":["Stock exceeds capacity","An item is unavailable when needed","An item is near expiry","A store is audited"],"correctIndex":1,"explanation":"A stock-out means the required item has zero usable stock at the point of need.","explanationNe":"आवश्यक परेको समयमा प्रयोगयोग्य मौज्दात शून्य हुनु stock-out हो।"}'::jsonb,true),
('dph-pm-extra-mcq-08','Pharmacy','Diploma in Pharmacy','mcq','free',1408,'{"question":"FEFO stands for:","translation":"FEFO को पूरा रूप के हो?","options":["First Expired, First Out","First Entered, First Ordered","Final Expiry, Final Out","Fast Entry, Fast Output"],"correctIndex":0,"explanation":"FEFO issues the batch with the earliest expiry first.","explanationNe":"FEFO अनुसार सबैभन्दा पहिले म्याद सकिने ब्याच पहिले वितरण गरिन्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-09','Pharmacy','Diploma in Pharmacy','mcq','free',1409,'{"question":"FIFO is especially useful when:","translation":"FIFO कुन अवस्थामा उपयोगी हुन्छ?","options":["Expiry dates are absent or equivalent","Only cold-chain products are stored","No stock records exist","Medicines are recalled"],"correctIndex":0,"explanation":"FIFO issues older received stock first; FEFO is preferred when expiry dates differ.","explanationNe":"FIFO मा पहिले आएको सामान पहिले निकालिन्छ; म्याद फरक भए FEFO प्राथमिक हुन्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-10','Pharmacy','Diploma in Pharmacy','mcq','free',1410,'{"question":"ABC analysis classifies inventory mainly by:","translation":"ABC विश्लेषणले मौज्दातलाई मुख्यतः केका आधारमा वर्गीकरण गर्छ?","options":["Annual consumption value","Colour of package","Dosage form","Manufacturer country"],"correctIndex":0,"explanation":"ABC identifies items by annual consumption value to focus financial control.","explanationNe":"वार्षिक खपत मूल्यका आधारमा वस्तु छुट्याएर आर्थिक नियन्त्रणमा ध्यान दिन्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-11','Pharmacy','Diploma in Pharmacy','mcq','free',1411,'{"question":"In ABC analysis, category A items usually represent:","translation":"ABC विश्लेषणमा A वर्गका वस्तु सामान्यतया कस्ता हुन्छन्?","options":["Many items with low total value","Few items with high annual value","Expired items only","Items with no demand"],"correctIndex":1,"explanation":"A items are relatively few but account for a large share of total inventory value.","explanationNe":"A वर्गका वस्तु संख्या कम भए पनि कुल मौज्दात मूल्यको ठूलो हिस्सा ओगट्छन्।"}'::jsonb,true),
('dph-pm-extra-mcq-12','Pharmacy','Diploma in Pharmacy','mcq','free',1412,'{"question":"VEN analysis classifies medicines as:","translation":"VEN विश्लेषणले औषधिलाई कसरी वर्गीकरण गर्छ?","options":["Vital, Essential, Non-essential","Verified, Expired, New","Value, Expense, Number","Vaccine, Emergency, Normal"],"correctIndex":0,"explanation":"VEN prioritizes medicines by their clinical importance.","explanationNe":"VEN ले चिकित्सकीय महत्त्वका आधारमा औषधिको प्राथमिकता निर्धारण गर्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-13','Pharmacy','Diploma in Pharmacy','mcq','free',1413,'{"question":"A medicine that is life-saving and must not be unavailable is usually:","translation":"जीवनरक्षक र अभाव हुन नहुने औषधि कुन VEN वर्गमा पर्छ?","options":["Non-essential","Vital","Optional","Obsolete"],"correctIndex":1,"explanation":"Vital medicines are critical for saving life or preventing serious harm.","explanationNe":"Vital औषधि जीवन बचाउन वा गम्भीर हानि रोक्न अत्यन्त आवश्यक हुन्छन्।"}'::jsonb,true),
('dph-pm-extra-mcq-14','Pharmacy','Diploma in Pharmacy','mcq','free',1414,'{"question":"ABC-VEN matrix is useful because it combines:","translation":"ABC-VEN matrix किन उपयोगी हुन्छ?","options":["Cost and clinical criticality","Colour and shape","Brand and manufacturer","Expiry and packaging only"],"correctIndex":0,"explanation":"It helps prioritize procurement and inventory control using both value and importance.","explanationNe":"यसले मूल्य र चिकित्सकीय महत्त्व दुवैका आधारमा खरिद तथा मौज्दात नियन्त्रणमा प्राथमिकता दिन्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-15','Pharmacy','Diploma in Pharmacy','mcq','free',1415,'{"question":"A purchase order is a document used to:","translation":"Purchase order कुन कामका लागि प्रयोग हुन्छ?","options":["Request or authorize purchase from a supplier","Record patient diagnosis","Prescribe medicine","Dispose of waste"],"correctIndex":0,"explanation":"It formally specifies items, quantities, prices and delivery terms for procurement.","explanationNe":"यसले खरिद गरिने वस्तु, परिमाण, मूल्य र आपूर्ति सर्त औपचारिक रूपमा उल्लेख गर्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-16','Pharmacy','Diploma in Pharmacy','mcq','free',1416,'{"question":"Competitive bidding aims to:","translation":"प्रतिस्पर्धात्मक बोलपत्रको उद्देश्य के हो?","options":["Ensure fair competition and value for money","Select the first supplier without review","Avoid specifications","Increase corruption risk"],"correctIndex":0,"explanation":"Transparent competition can improve fairness, quality and cost-effectiveness.","explanationNe":"पारदर्शी प्रतिस्पर्धाले निष्पक्षता, गुणस्तर र लागत प्रभावकारिता बढाउन सक्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-17','Pharmacy','Diploma in Pharmacy','mcq','free',1417,'{"question":"A goods-received note confirms:","translation":"Goods-received note ले के पुष्टि गर्छ?","options":["Items received and checked","Patient has recovered","Supplier has been paid","Medicine has been prescribed"],"correctIndex":0,"explanation":"It documents receipt and inspection of delivered goods against the order.","explanationNe":"यसले अर्डरअनुसार सामान प्राप्त र जाँच गरिएको अभिलेख राख्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-18','Pharmacy','Diploma in Pharmacy','mcq','free',1418,'{"question":"On receiving medicines, staff should first check:","translation":"औषधि प्राप्त गर्दा कर्मचारीले पहिले के जाँच गर्नुपर्छ?","options":["Quantity, condition, batch and expiry","Only package colour","Only supplier logo","Retail selling price"],"correctIndex":0,"explanation":"Receipt checks detect shortages, damage, wrong items and expiry problems.","explanationNe":"प्राप्ति जाँचले कमी, क्षति, गलत सामान र म्यादसम्बन्धी समस्या पत्ता लगाउँछ।"}'::jsonb,true),
('dph-pm-extra-mcq-19','Pharmacy','Diploma in Pharmacy','mcq','free',1419,'{"question":"A cold-chain medicine should be stored:","translation":"Cold-chain औषधि कसरी भण्डारण गर्नुपर्छ?","options":["At the labelled temperature range","Beside a sunny window","At any convenient temperature","In a freezer in every case"],"correctIndex":0,"explanation":"Follow the product label and applicable cold-chain guidance; freezing may damage some products.","explanationNe":"लेबल र लागू cold-chain निर्देशनअनुसार राख्नुपर्छ; केही औषधि जमाउँदा बिग्रन सक्छन्।"}'::jsonb,true),
('dph-pm-extra-mcq-20','Pharmacy','Diploma in Pharmacy','mcq','free',1420,'{"question":"Temperature monitoring records are important because they:","translation":"तापक्रम अभिलेख किन महत्त्वपूर्ण हुन्छ?","options":["Show storage conditions over time","Replace expiry checks","Guarantee all medicines are effective","Remove need for refrigerators"],"correctIndex":0,"explanation":"Records help identify excursions and support decisions on affected stock.","explanationNe":"अभिलेखले तापक्रम सीमा बाहिर गएको अवस्था पहिचान गरी प्रभावित औषधिबारे निर्णय गर्न मद्दत गर्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-21','Pharmacy','Diploma in Pharmacy','mcq','free',1421,'{"question":"A quarantine area is used for:","translation":"Quarantine क्षेत्र केका लागि प्रयोग हुन्छ?","options":["Separating stock pending investigation or decision","Storing all fast-moving items","Displaying promotional products","Keeping staff belongings"],"correctIndex":0,"explanation":"Suspected damaged, recalled or otherwise questionable stock is segregated pending disposition.","explanationNe":"शंकास्पद, क्षतिग्रस्त वा फिर्ता बोलाइएको मौज्दात निर्णय नहुँदासम्म छुट्टै राखिन्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-22','Pharmacy','Diploma in Pharmacy','mcq','free',1422,'{"question":"A standard operating procedure (SOP) provides:","translation":"SOP ले के प्रदान गर्छ?","options":["Written step-by-step instructions","A verbal rumour","A supplier advertisement","A patient diagnosis"],"correctIndex":0,"explanation":"SOPs standardize routine tasks and reduce variation and errors.","explanationNe":"SOP ले नियमित कामलाई मानकीकृत गरी फरकपन र त्रुटि घटाउँछ।"}'::jsonb,true),
('dph-pm-extra-mcq-23','Pharmacy','Diploma in Pharmacy','mcq','free',1423,'{"question":"The purpose of an inventory card is to record:","translation":"Inventory card मा के अभिलेख गरिन्छ?","options":["Receipts, issues and balance","Only staff attendance","Patient blood pressure","Only purchase price"],"correctIndex":0,"explanation":"A stock card tracks every movement and the remaining balance of an item.","explanationNe":"Stock card ले सामानको प्राप्ति, निकासा र बाँकी मौज्दात देखाउँछ।"}'::jsonb,true),
('dph-pm-extra-mcq-24','Pharmacy','Diploma in Pharmacy','mcq','free',1424,'{"question":"Physical stock verification means:","translation":"Physical stock verification भन्नाले के बुझिन्छ?","options":["Counting actual stock and comparing records","Changing expiry dates","Ordering without checking","Reviewing only invoices"],"correctIndex":0,"explanation":"It detects discrepancies between actual quantities and recorded balances.","explanationNe":"यसले वास्तविक मौज्दात र अभिलेखबीचको फरक पत्ता लगाउँछ।"}'::jsonb,true),
('dph-pm-extra-mcq-25','Pharmacy','Diploma in Pharmacy','mcq','free',1425,'{"question":"A discrepancy between physical and recorded stock should be:","translation":"भौतिक र अभिलेखित मौज्दात फरक भए के गर्नुपर्छ?","options":["Ignored","Investigated and documented","Corrected secretly","Blamed automatically on supplier"],"correctIndex":1,"explanation":"Investigate transactions, document findings and authorize corrections according to policy.","explanationNe":"कारोबार जाँचेर निष्कर्ष अभिलेख गर्नुपर्छ र नीतिअनुसार स्वीकृत सुधार गर्नुपर्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-26','Pharmacy','Diploma in Pharmacy','mcq','free',1426,'{"question":"A near-expiry report helps a pharmacy to:","translation":"Near-expiry report ले केमा मद्दत गर्छ?","options":["Take timely action to minimize wastage","Hide expired products","Stop stock rotation","Avoid checking batches"],"correctIndex":0,"explanation":"It supports redistribution, careful issuing and timely procurement adjustment.","explanationNe":"यसले पुनर्वितरण, सावधानीपूर्वक वितरण र खरिद समायोजनमा मद्दत गर्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-27','Pharmacy','Diploma in Pharmacy','mcq','free',1427,'{"question":"Expired medicines should be:","translation":"म्याद सकिएका औषधिलाई के गर्नुपर्छ?","options":["Dispensed at a discount","Segregated and disposed through approved procedures","Mixed with usable stock","Relabelled"],"correctIndex":1,"explanation":"Expired stock must not be supplied and should be handled under applicable disposal rules.","explanationNe":"म्याद सकिएको औषधि वितरण गर्नु हुँदैन र लागू नियमअनुसार व्यवस्थापन गर्नुपर्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-28','Pharmacy','Diploma in Pharmacy','mcq','free',1428,'{"question":"A budget is best described as:","translation":"Budget लाई कसरी परिभाषित गर्न सकिन्छ?","options":["A financial plan for a defined period","A stock card","A prescription","A quality defect"],"correctIndex":0,"explanation":"A budget estimates expected income and expenditure for a period or activity.","explanationNe":"Budget ले निश्चित अवधि वा गतिविधिको अनुमानित आम्दानी र खर्च देखाउँछ।"}'::jsonb,true),
('dph-pm-extra-mcq-29','Pharmacy','Diploma in Pharmacy','mcq','free',1429,'{"question":"Variance analysis compares:","translation":"Variance analysis ले के तुलना गर्छ?","options":["Actual results with budgeted figures","Two package colours","Patient age with height","Only supplier names"],"correctIndex":0,"explanation":"It identifies differences between planned and actual expenditure or performance.","explanationNe":"यसले योजनाबद्ध र वास्तविक खर्च वा कार्यसम्पादनबीचको अन्तर देखाउँछ।"}'::jsonb,true),
('dph-pm-extra-mcq-30','Pharmacy','Diploma in Pharmacy','mcq','free',1430,'{"question":"A key purpose of staff training is to:","translation":"कर्मचारी तालिमको मुख्य उद्देश्य के हो?","options":["Improve competence and safe work practices","Replace written procedures","Increase dispensing errors","Avoid supervision"],"correctIndex":0,"explanation":"Training improves knowledge, skills and adherence to procedures.","explanationNe":"तालिमले ज्ञान, सीप र कार्यविधि पालना गर्ने क्षमता बढाउँछ।"}'::jsonb,true),
('dph-pm-extra-mcq-31','Pharmacy','Diploma in Pharmacy','mcq','free',1431,'{"question":"Segregation of duties helps to:","translation":"कामको जिम्मेवारी छुट्याउँदा के फाइदा हुन्छ?","options":["Reduce error and fraud risk","Remove accountability","Avoid documentation","Increase unauthorized access"],"correctIndex":0,"explanation":"Separating ordering, receiving and payment roles strengthens internal control.","explanationNe":"अर्डर, प्राप्ति र भुक्तानीको जिम्मेवारी छुट्याउँदा आन्तरिक नियन्त्रण बलियो हुन्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-32','Pharmacy','Diploma in Pharmacy','mcq','free',1432,'{"question":"A procurement specification should be:","translation":"खरिद specification कस्तो हुनुपर्छ?","options":["Clear, objective and non-discriminatory","Vague and brand-biased","Changed after delivery","Based only on colour"],"correctIndex":0,"explanation":"Clear specifications define quality, strength, dosage form, pack and other requirements.","explanationNe":"स्पष्ट specification ले गुणस्तर, शक्ति, dosage form, प्याक र अन्य आवश्यकता जनाउँछ।"}'::jsonb,true),
('dph-pm-extra-mcq-33','Pharmacy','Diploma in Pharmacy','mcq','free',1433,'{"question":"The reorder level indicates:","translation":"Reorder level ले के जनाउँछ?","options":["The stock level at which a new order should be placed","The expiry date","The maximum retail price","The number of staff"],"correctIndex":0,"explanation":"It triggers replenishment early enough to cover lead time and safety stock.","explanationNe":"Lead time र safety stock धान्न समयमै पुनः अर्डर गर्नुपर्ने मौज्दात स्तर हो।"}'::jsonb,true),
('dph-pm-extra-mcq-34','Pharmacy','Diploma in Pharmacy','mcq','free',1434,'{"question":"Economic order quantity is intended to balance:","translation":"Economic order quantity ले के सन्तुलन गर्छ?","options":["Ordering and holding costs","Patient and staff ages","Expiry and batch numbers","Brand and generic names"],"correctIndex":0,"explanation":"EOQ seeks a quantity that balances ordering costs with inventory holding costs under its assumptions.","explanationNe":"EOQ ले निश्चित मान्यताअन्तर्गत अर्डर खर्च र मौज्दात राख्ने खर्च सन्तुलन गर्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-35','Pharmacy','Diploma in Pharmacy','mcq','free',1435,'{"question":"A medicine recall requires the pharmacy to:","translation":"औषधि recall हुँदा फार्मेसीले के गर्नुपर्छ?","options":["Identify, segregate and follow recall instructions","Continue dispensing until empty","Delete purchase records","Change batch labels"],"correctIndex":0,"explanation":"Trace affected batches, stop supply, segregate stock and document actions.","explanationNe":"प्रभावित ब्याच पहिचान गरी वितरण रोक्ने, छुट्याउने र सबै काम अभिलेख गर्नुपर्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-36','Pharmacy','Diploma in Pharmacy','mcq','free',1436,'{"question":"Quality assurance in a pharmacy focuses on:","translation":"फार्मेसीमा Quality Assurance ले केमा ध्यान दिन्छ?","options":["Consistent compliance with defined quality requirements","Sales volume only","Package appearance only","Reducing all documentation"],"correctIndex":0,"explanation":"QA uses systems and checks to ensure processes and products meet requirements.","explanationNe":"QA ले प्रक्रिया र उत्पादनले तोकिएको गुणस्तर पूरा गरेको सुनिश्चित गर्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-37','Pharmacy','Diploma in Pharmacy','mcq','free',1437,'{"question":"An internal audit is conducted to:","translation":"Internal audit किन गरिन्छ?","options":["Assess compliance and identify improvement opportunities","Punish every staff member","Replace all records","Advertise products"],"correctIndex":0,"explanation":"Audits review systems and evidence to identify gaps and corrective actions.","explanationNe":"Audit ले प्रणाली र प्रमाण जाँचेर कमजोरी तथा सुधारका उपाय पहिचान गर्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-38','Pharmacy','Diploma in Pharmacy','mcq','free',1438,'{"question":"A corrective action is intended to:","translation":"Corrective action को उद्देश्य के हो?","options":["Address the cause of an identified problem","Hide the problem","Repeat the same error","Discard all records"],"correctIndex":0,"explanation":"Corrective action addresses the cause to reduce recurrence.","explanationNe":"Corrective action ले समस्याको मूल कारण समाधान गरी पुनरावृत्ति घटाउँछ।"}'::jsonb,true),
('dph-pm-extra-mcq-39','Pharmacy','Diploma in Pharmacy','mcq','free',1439,'{"question":"Ethical procurement requires:","translation":"नैतिक खरिदका लागि के आवश्यक हुन्छ?","options":["Transparency, fairness and management of conflicts of interest","Secret supplier preference","Undisclosed personal benefits","False documentation"],"correctIndex":0,"explanation":"Ethical procurement avoids favoritism and requires transparent decisions.","explanationNe":"नैतिक खरिदमा पक्षपातबाट बच्दै पारदर्शी निर्णय आवश्यक हुन्छ।"}'::jsonb,true),
('dph-pm-extra-mcq-40','Pharmacy','Diploma in Pharmacy','mcq','free',1440,'{"question":"The most appropriate response to suspected pilferage is to:","translation":"औषधि चोरी/हिनामिना शंका लागेमा उपयुक्त कदम के हो?","options":["Follow reporting and investigation procedures","Accuse publicly without evidence","Alter stock records","Ignore it"],"correctIndex":0,"explanation":"Report through the authorized process and preserve accurate records and evidence.","explanationNe":"अधिकृत प्रक्रियाबाट जानकारी दिई सही अभिलेख र प्रमाण सुरक्षित राख्नुपर्छ।"}'::jsonb,true),
('dph-pm-extra-mock-01','Pharmacy','Diploma in Pharmacy','mock','free',1501,'{"question":"Explain the main stages of the pharmaceutical supply management cycle.","answer":"The cycle includes selection, quantification, procurement, receipt, storage, inventory control, distribution and monitoring.","answerNe":"यसमा छनोट, परिमाण निर्धारण, खरिद, प्राप्ति, भण्डारण, मौज्दात नियन्त्रण, वितरण र अनुगमन पर्छन्।"}'::jsonb,true),
('dph-pm-extra-mock-02','Pharmacy','Diploma in Pharmacy','mock','free',1502,'{"question":"Differentiate FIFO and FEFO with an example.","answer":"FIFO issues the oldest received stock first. FEFO issues the batch with the earliest expiry first. If a newer batch expires sooner, FEFO takes priority.","answerNe":"FIFO मा पहिले आएको सामान पहिले निकालिन्छ। FEFO मा पहिले म्याद सकिने ब्याच पहिले निकालिन्छ। नयाँ ब्याचको म्याद पहिले सकिँदैछ भने FEFO लागू हुन्छ।"}'::jsonb,true),
('dph-pm-extra-mock-03','Pharmacy','Diploma in Pharmacy','mock','free',1503,'{"question":"Describe ABC analysis and its use in pharmacy inventory control.","answer":"ABC groups items by annual consumption value: A high-value, B medium-value and C low-value. It helps focus monitoring and financial control on high-value items.","answerNe":"ABC ले वार्षिक खपत मूल्यका आधारमा A उच्च, B मध्यम र C कम मूल्यका वस्तु छुट्याउँछ। यसले महँगा वस्तुमा बढी निगरानी गर्न मद्दत गर्छ।"}'::jsonb,true),
('dph-pm-extra-mock-04','Pharmacy','Diploma in Pharmacy','mock','free',1504,'{"question":"Explain VEN analysis and why it is combined with ABC.","answer":"VEN classifies medicines as Vital, Essential and Non-essential by clinical importance. Combining it with ABC balances financial value and clinical criticality.","answerNe":"VEN ले चिकित्सकीय महत्त्वका आधारमा Vital, Essential र Non-essential छुट्याउँछ। ABC सँग जोड्दा आर्थिक मूल्य र चिकित्सकीय आवश्यकता दुवै विचार हुन्छ।"}'::jsonb,true),
('dph-pm-extra-mock-05','Pharmacy','Diploma in Pharmacy','mock','free',1505,'{"question":"List the information that should be checked when receiving a medicine consignment.","answer":"Check purchase order, item name, strength, dosage form, quantity, batch, expiry, packaging integrity, storage/temperature conditions and required documents.","answerNe":"Purchase order, औषधिको नाम, शक्ति, dosage form, परिमाण, ब्याच, म्याद, प्याकेजको अवस्था, तापक्रम र आवश्यक कागजात जाँच्नुपर्छ।"}'::jsonb,true),
('dph-pm-extra-mock-06','Pharmacy','Diploma in Pharmacy','mock','free',1506,'{"question":"What is lead time? Explain its importance in setting reorder levels.","answer":"Lead time is the time from placing an order to receiving usable stock. Longer or variable lead time requires earlier reordering and suitable safety stock.","answerNe":"अर्डरदेखि प्रयोगयोग्य सामान प्राप्त हुँदासम्मको अवधि lead time हो। लामो वा परिवर्तनशील lead time भए छिटो पुनः अर्डर र उपयुक्त safety stock चाहिन्छ।"}'::jsonb,true),
('dph-pm-extra-mock-07','Pharmacy','Diploma in Pharmacy','mock','free',1507,'{"question":"Describe safe storage practices for medicines.","answer":"Store according to labelled conditions, protect from heat, light and moisture, maintain cleanliness and security, monitor temperature, separate hazardous or quarantined stock and rotate by FEFO.","answerNe":"लेबलअनुसार भण्डारण, ताप, प्रकाश र चिस्यानबाट सुरक्षा, सफाइ र सुरक्षा, तापक्रम अनुगमन, शंकास्पद मौज्दात छुट्याउने र FEFO अपनाउनुपर्छ।"}'::jsonb,true),
('dph-pm-extra-mock-08','Pharmacy','Diploma in Pharmacy','mock','free',1508,'{"question":"What actions should be taken when a refrigerator temperature excursion is detected?","answer":"Do not automatically use or discard affected stock. Quarantine/label it, record the excursion, inform the responsible person, assess stability using authoritative guidance or manufacturer advice, and document the decision.","answerNe":"प्रभावित औषधि तुरुन्त प्रयोग वा फाल्नु हुँदैन। छुट्याएर लेबल लगाउने, तापक्रम अभिलेख गर्ने, जिम्मेवार व्यक्तिलाई जानकारी दिने, आधिकारिक निर्देशन/निर्माताको सल्लाहअनुसार मूल्याङ्कन गर्ने र निर्णय लेख्ने।"}'::jsonb,true),
('dph-pm-extra-mock-09','Pharmacy','Diploma in Pharmacy','mock','free',1509,'{"question":"Explain the purpose of a stock card and the entries it contains.","answer":"A stock card tracks receipts, issues, dates, quantities, batch/expiry where applicable, reference documents and running balance.","answerNe":"Stock card ले प्राप्ति, निकासा, मिति, परिमाण, आवश्यकतानुसार ब्याच/म्याद, कागजात सन्दर्भ र बाँकी मौज्दात देखाउँछ।"}'::jsonb,true),
('dph-pm-extra-mock-10','Pharmacy','Diploma in Pharmacy','mock','free',1510,'{"question":"How should a stock discrepancy be investigated?","answer":"Recount stock, review receipts and issues, check transfers, returns and adjustments, verify units and documentation, report findings and make only authorized corrections.","answerNe":"मौज्दात पुनः गन्ने, प्राप्ति/निकासा, स्थानान्तरण, फिर्ता र समायोजन जाँच्ने, एकाइ तथा कागजात मिलाउने, निष्कर्ष रिपोर्ट गर्ने र स्वीकृत सुधार मात्र गर्ने।"}'::jsonb,true),
('dph-pm-extra-mock-11','Pharmacy','Diploma in Pharmacy','mock','free',1511,'{"question":"Describe the steps in a transparent medicine procurement process.","answer":"Assess need, prepare specifications, estimate quantity and budget, obtain quotations/tenders as required, evaluate suppliers objectively, approve award, issue purchase order and monitor delivery.","answerNe":"आवश्यकता पहिचान, specification, परिमाण/बजेट, आवश्यक बोलपत्र/दरभाउ, निष्पक्ष मूल्याङ्कन, स्वीकृति, purchase order र आपूर्ति अनुगमन गर्नुपर्छ।"}'::jsonb,true),
('dph-pm-extra-mock-12','Pharmacy','Diploma in Pharmacy','mock','free',1512,'{"question":"Why are clear specifications important in medicine procurement?","answer":"They ensure the requested medicine meets required quality, strength, dosage form, pack size and regulatory conditions, while supporting fair supplier comparison.","answerNe":"स्पष्ट specification ले गुणस्तर, शक्ति, dosage form, प्याक र नियामक सर्त पूरा गराउँछ र आपूर्तिकर्ताबीच निष्पक्ष तुलना सम्भव बनाउँछ।"}'::jsonb,true),
('dph-pm-extra-mock-13','Pharmacy','Diploma in Pharmacy','mock','free',1513,'{"question":"Explain buffer stock and mention factors that influence its level.","answer":"Buffer stock is extra stock against demand or supply uncertainty. Its level depends on consumption variability, lead time, supplier reliability, storage capacity and expiry risk.","answerNe":"Buffer stock माग वा आपूर्ति अनिश्चितताविरुद्धको अतिरिक्त मौज्दात हो। खपतको उतारचढाव, lead time, आपूर्तिकर्ताको विश्वसनीयता, भण्डारण क्षमता र म्याद जोखिमले यसको स्तर निर्धारण गर्छ।"}'::jsonb,true),
('dph-pm-extra-mock-14','Pharmacy','Diploma in Pharmacy','mock','free',1514,'{"question":"What is a stock-out? State its consequences and prevention methods.","answer":"A stock-out is absence of usable stock when needed. It can interrupt treatment and cause emergency purchasing. Forecasting, reorder levels, monitoring and reliable procurement help prevent it.","answerNe":"आवश्यक समयमा प्रयोगयोग्य मौज्दात नहुनु stock-out हो। उपचार रोकिन सक्छ र आकस्मिक खरिद गर्नुपर्छ। अनुमान, reorder level, अनुगमन र भरपर्दो खरिदले रोकथाम गर्छ।"}'::jsonb,true),
('dph-pm-extra-mock-15','Pharmacy','Diploma in Pharmacy','mock','free',1515,'{"question":"Explain the role of SOPs in pharmacy operations.","answer":"SOPs provide approved written steps for recurring tasks, improve consistency, support training, clarify responsibility and reduce preventable errors.","answerNe":"SOP ले दोहोरिने कामका स्वीकृत लिखित चरण दिन्छ, एकरूपता बढाउँछ, तालिममा सहयोग गर्छ, जिम्मेवारी स्पष्ट पार्छ र रोक्न सकिने त्रुटि घटाउँछ।"}'::jsonb,true),
('dph-pm-extra-mock-16','Pharmacy','Diploma in Pharmacy','mock','free',1516,'{"question":"What is a pharmacy budget? Explain budget variance.","answer":"A budget is a financial plan for a period. Variance is the difference between actual and planned figures; it should be analysed to understand causes and take appropriate action.","answerNe":"Budget निश्चित अवधिको आर्थिक योजना हो। वास्तविक र योजनाबद्ध रकमबीचको फरक variance हो; कारण विश्लेषण गरी उपयुक्त कदम चाल्नुपर्छ।"}'::jsonb,true),
('dph-pm-extra-mock-17','Pharmacy','Diploma in Pharmacy','mock','free',1517,'{"question":"Describe the importance of physical inventory verification.","answer":"It confirms actual quantities, detects record errors, loss, damage and expiry, and supports accurate ordering and accountability.","answerNe":"यसले वास्तविक परिमाण पुष्टि गर्छ, अभिलेख त्रुटि, हराएको/क्षतिग्रस्त/म्याद सकिएको सामान पत्ता लगाउँछ र सही खरिद तथा जवाफदेहिता बढाउँछ।"}'::jsonb,true),
('dph-pm-extra-mock-18','Pharmacy','Diploma in Pharmacy','mock','free',1518,'{"question":"What should be done with expired, damaged or recalled medicines?","answer":"Segregate and clearly label them, prevent dispensing, record quantities and batches, notify the responsible authority and follow approved return or disposal procedures.","answerNe":"म्याद सकिएका, क्षतिग्रस्त वा recall भएका औषधि छुट्याएर स्पष्ट लेबल लगाउने, वितरण रोक्ने, परिमाण/ब्याच अभिलेख गर्ने र स्वीकृत फिर्ता वा नष्ट गर्ने प्रक्रिया अपनाउने।"}'::jsonb,true),
('dph-pm-extra-mock-19','Pharmacy','Diploma in Pharmacy','mock','free',1519,'{"question":"Explain the importance of documentation and accountability in pharmacy management.","answer":"Accurate records provide traceability, support stock control, enable audits, help investigate errors and demonstrate compliance and responsible use of resources.","answerNe":"सही अभिलेखले traceability, मौज्दात नियन्त्रण, audit, त्रुटि अनुसन्धान र नियमपालना प्रमाणित गर्न मद्दत गर्छ।"}'::jsonb,true),
('dph-pm-extra-mock-20','Pharmacy','Diploma in Pharmacy','mock','free',1520,'{"question":"Describe how a pharmacy can reduce medicine wastage.","answer":"Use reliable forecasting, FEFO, near-expiry monitoring, appropriate order quantities, good storage, stock redistribution where permitted and timely review of slow-moving items.","answerNe":"विश्वसनीय अनुमान, FEFO, म्याद नजिकका औषधिको निगरानी, उचित खरिद परिमाण, राम्रो भण्डारण, अनुमति भए पुनर्वितरण र कम चल्ने वस्तुको समीक्षा गर्नुपर्छ।"}'::jsonb,true)
